syntax:
class Singleton {
  private static instance: Singleton
  static getInstance() { ... }
}

example:
class ConexaoBanco {
  private static instance: ConexaoBanco
  private constructor() {}
  static getInstance() {
    if (!ConexaoBanco.instance) {
      ConexaoBanco.instance = new ConexaoBanco()
    }
    return ConexaoBanco.instance
  }
}

interface EstrategiaFrete {
  calcular(peso: number): number
}
class FreteExpresso implements EstrategiaFrete {
  calcular(peso: number) { return peso * 2.5 }
}
class Carrinho {
  constructor(private frete: EstrategiaFrete) {}
  calcularTotal(peso: number) { return this.frete.calcular(peso) }
}
